* SQL / Database Submenu (admin only)
MAP SQLMENU SIZE 24x80
  FIELD AT 1,1  LEN 6  PROT BRIGHT COLOR=GREEN  "MYIF06"
  FIELD AT 1,25 LEN 30 PROT BRIGHT COLOR=GREEN  "SQL / DATABASE"
  INPUT DATFLD  AT 1,65 LEN 10 PROT COLOR=GREEN
  STOP          AT 1,75
  FIELD AT 2,1  LEN 8  PROT COLOR=GREEN         "SQLMENU0"
  INPUT USRFLD  AT 2,28 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,36
  INPUT TIMFLD  AT 2,65 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,73

  FIELD AT 3,3  LEN 20 PROT BRIGHT COLOR=GREEN  "--- REXX ---"
  INPUT L01 AT 4,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 4,41
  FIELD AT 5,3  LEN 20 PROT BRIGHT COLOR=GREEN  "--- COBOL ---"
  INPUT L02 AT 6,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 6,41

  INPUT ROLEFLD AT 21,40 LEN 20 PROT COLOR=GREEN
  STOP          AT 21,60
  FIELD AT 21,3  LEN 12 PROT COLOR=GREEN     "SELECTION =>"
  INPUT SELFLD   AT 21,16 LEN 2 UNPROT COLOR=GREEN
  STOP           AT 21,19

  FIELD AT 24,1 LEN 78 PROT COLOR=GREEN  "PF:  1 LOGOFF    3 MAIN MENU    9 HELP                  7 BWD   8 FWD"
  CURSOR AT SELFLD
ENDMAP
